// ── Searchable value help ─────────────────────────────────────────────────────
function ValueHelp({
  value,
  onChange,
  placeholder,
  values,
  label,
  selectionOnly = false,
  inputStyle,
  showInnerSearch = true,
}: {
  value: string
  onChange: (v: string) => void
  placeholder?: string
  values: string[]
  label?: string
  selectionOnly?: boolean
  inputStyle?: React.CSSProperties
  showInnerSearch?: boolean
}) {
  const [open, setOpen] = useState(false)
  const [inner, setInner] = useState("")
  // Track whether the mouse is anywhere inside the dropdown.
  // This prevents the main input's onBlur from closing the panel
  // when the user clicks the inner search or hovers over items.
  const dropRef = useState(false)
  const dropHover = dropRef[0]
  const setDropHover = dropRef[1]

  const close = () => {
    setOpen(false)
    setInner("")
  }

  const optionQuery = inner || (selectionOnly ? "" : value)
  const filtered = values.filter((v) =>
    !optionQuery || !activeSearch(optionQuery)
      ? true
      : v.toLowerCase().includes(optionQuery.trim().toLowerCase()),
  )

  return (
    <div style={{ position: "relative", flex: 1 }}>
      {label && (
        <div
          style={{
            fontSize: 11,
            fontWeight: 600,
            color: F.text2,
            marginBottom: 3,
            textTransform: "uppercase",
            letterSpacing: "0.06em",
          }}
        >
          {label}
        </div>
      )}
      <div style={{ position: "relative" }}>
        <input
          value={value}
          readOnly={selectionOnly}
          onChange={(e) => onChange(e.target.value)}
          onFocus={() => {
            setOpen(true)
            setInner("")
          }}
          onBlur={() => {
            if (!dropHover) close()
          }}
          placeholder={placeholder ?? "Search…"}
          style={{
            ...iSt,
            ...inputStyle,
            paddingLeft: 10,
            paddingRight: value || selectionOnly ? 32 : 10,
            cursor: selectionOnly ? "pointer" : undefined,
            border: `1px solid ${open ? F.brand : F.border}`,
            boxShadow: open ? `0 0 0 2px ${F.brand}22` : undefined,
            transition: "border 0.12s, box-shadow 0.12s",
          }}
        />
        {value && !selectionOnly && (
          <button
            title="Clear search"
            onMouseDown={(e) => {
              e.preventDefault()
              onChange("")
              close()
            }}
            style={{
              position: "absolute",
              right: 8,
              top: "50%",
              transform: "translateY(-50%)",
              background: "none",
              border: "none",
              cursor: "pointer",
              color: F.text3,
              fontSize: 16,
              lineHeight: 1,
            }}
          >
            ×
          </button>
        )}
        {selectionOnly && (
          <span
            aria-hidden="true"
            style={{
              position: "absolute",
              right: 9,
              top: "50%",
              transform: "translateY(-50%)",
              color: F.text3,
              pointerEvents: "none",
              display: "flex",
            }}
          >
            <UiIcon name="chevronDown" size={15} />
          </span>
        )}
      </div>

      {open && (
        <div
          onMouseEnter={() => setDropHover(true)}
          onMouseLeave={() => setDropHover(false)}
          style={{
            position: "absolute",
            top: "calc(100% + 4px)",
            left: 0,
            right: 0,
            minWidth: 260,
            background: F.card,
            border: `1px solid ${F.brand}`,
            borderRadius: 6,
            zIndex: 400,
            boxShadow: "0 8px 28px rgba(0,0,0,0.16)",
            overflow: "hidden",
          }}
        >
          {/* Inner search — no autoFocus; stays open because dropHover is true */}
          {showInnerSearch && (
            <>
          <div
            style={{
              padding: "8px 10px",
              borderBottom: `1px solid ${F.border}`,
              background: F.pageBg,
            }}
          >
            <div style={{ position: "relative" }}>
              <input
                value={inner}
                onChange={(e) => setInner(e.target.value)}
                onBlur={() => {
                  if (!dropHover) close()
                }}
                placeholder="Search available values…"
                style={{ ...iSt, paddingLeft: 10, fontSize: 12 }}
              />
            </div>
          </div>
            </>
          )}

          <div style={{ maxHeight: 240, overflowY: "auto" }}>
            {filtered.length === 0 && (
              <div
                style={{
                  padding: "16px 14px",
                  fontSize: 13,
                  color: F.text3,
                  textAlign: "center",
                }}
              >
                No results for "{optionQuery}"
              </div>
            )}
            {optionQuery && !activeSearch(optionQuery) && (
              <div
                style={{
                  padding: "8px 14px",
                  fontSize: 12,
                  color: F.text3,
                  background: F.infoBg,
                  borderBottom: `1px solid ${F.border}`,
                }}
              >
                Type at least 3 characters to search.
              </div>
            )}
            {filtered.map((v) => (
              <div
                key={v}
                // onMouseDown with preventDefault keeps focus on the currently-focused
                // input (main or inner) so the blur/close cycle never triggers.
                onMouseDown={(e) => {
                  e.preventDefault()
                  onChange(v)
                  close()
                }}
                style={{
                  padding: "9px 14px",
                  fontSize: 13,
                  color: v === value ? F.brand : F.text1,
                  background: v === value ? F.infoBg : "transparent",
                  cursor: "pointer",
                  fontWeight: v === value ? 600 : 400,
                  borderBottom: `1px solid ${F.border}`,
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "space-between",
                  transition: "background 0.08s",
                }}
              >
                <span>{v}</span>
                {v === value && (
                  <span style={{ fontSize: 11, fontWeight: 800, color: F.brand }}>
                    Selected
                  </span>
                )}
              </div>
            ))}
          </div>

          <div
            style={{
              padding: "5px 12px",
              borderTop: `1px solid ${F.border}`,
              fontSize: 11,
              color: F.text3,
              display: "flex",
              justifyContent: "space-between",
              alignItems: "center",
              background: F.pageBg,
            }}
          >
            <span>Available Values</span>
            <span>
              {filtered.length} of {values.length}
            </span>
          </div>
        </div>
      )}
    </div>
  )
}

